import{_ as i,a0 as u,w as a,s,I as p,x as r,a1 as e,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action","title":"Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备","tag":"201508","desc":""},"relativePath":"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action.md","filePath":"[post].md"}'),l={name:"201508/20150816 Ubuntu NVIDIA Graphics Drivers PPA Is Ready For Action.md"};function P(A,t,I,b,m,g){const n=u("Link");return a(),s("div",null,[t[16]||(t[16]=p("h1",{id:"ubuntu-nvidia-显卡驱动-ppa-已经做好准备",tabindex:"-1"},[r("Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备 "),p("a",{class:"header-anchor",href:"#ubuntu-nvidia-显卡驱动-ppa-已经做好准备","aria-label":"Permalink to “Ubuntu NVIDIA 显卡驱动 PPA 已经做好准备”"},"​")],-1)),t[17]||(t[17]=p("p",null,[p("img",{src:"http://www.omgubuntu.co.uk/wp-content/uploads/2015/08/Screen-Shot-2015-08-12-at-14.19.42.png",alt:""})],-1)),t[18]||(t[18]=p("p",null,"加速你的帧率！",-1)),t[19]||(t[19]=p("p",null,[p("strong",null,"嘿，各位，稍安勿躁，很快就好。")],-1)),p("p",null,[t[1]||(t[1]=r("就在提议开发一个",-1)),e(n,{href:"https://linux.cn/article-6030-1.html"},{default:o(()=>[...t[0]||(t[0]=[r("新的 PPA",-1)])]),_:1}),t[2]||(t[2]=r(" 来给 Ubuntu 用户们提供最新的 NVIDIA 显卡驱动后不久，ubuntu 社区的人们又集结起来了，就是为了这件事。",-1))]),t[20]||(t[20]=d(`<p>顾名思义，‘<strong>Graphics Drivers PPA</strong>’ 包含了最新的 NVIDIA Linux 显卡驱动发布，已经打包好可供用户升级使用，没有让人头疼的二进制运行时文件！</p><p>这个 PPA 被设计用来让玩家们尽可能方便地在 Ubuntu 上运行最新款的游戏。</p><h4 id="万事俱备-只欠东风" tabindex="-1">万事俱备，只欠东风 <a class="header-anchor" href="#万事俱备-只欠东风" aria-label="Permalink to “万事俱备，只欠东风”">​</a></h4><p>Jorge Castro 开发一个包含 NVIDIA 最新显卡驱动的 PPA 神器的想法得到了 Ubuntu 用户和广大游戏开发者的热烈响应。</p><p>就连那些致力于将“Steam平台”上的知名大作移植到 Linux 上的人们，也给了不少建议。</p><p>Edwin Smith，Feral Interactive 公司(‘Shadow of Mordor’) 的产品总监，对于“让用户更方便地更新驱动”的倡议表示非常欣慰。</p><h3 id="如何使用最新的-nvidia-drivers-ppa" tabindex="-1">如何使用最新的 Nvidia Drivers PPA### <a class="header-anchor" href="#如何使用最新的-nvidia-drivers-ppa" aria-label="Permalink to “如何使用最新的 Nvidia Drivers PPA###”">​</a></h3><p>虽然新的“显卡PPA”已经开发出来，但是现在还远远达不到成熟。开发者们提醒到：</p><blockquote><p>“这个 PPA 还处于测试阶段，在你使用它之前最好有一些打包的经验。请大家稍安勿躁，再等几天。”</p></blockquote><p>将 PPA 试发布给 Ubuntu desktop 邮件列表的 Jorge，也强调说，使用现行的一些 PPA（比如 xorg-edgers)的玩家可能发现不了什么区别（因为现在的驱动只不过是把内容从其他那些现存驱动拷贝过来了）</p><p>“新驱动发布的时候，好戏才会上演呢，”他说。</p><p>截至写作本文时为止，这个 PPA 囊括了从 Ubuntu 12.04.1 到 15.10 各个版本的 Nvidia 驱动。注意这些驱动对所有的发行版都适用。</p><blockquote><p><strong>毫无疑问，除非你清楚自己在干些什么，并且知道如果出了问题应该怎么撤销，否则就不要进行下面的操作。</strong></p></blockquote><p>新打开一个终端窗口，运行下面的命令加入 PPA：</p><pre><code>sudo add-apt-repository ppa:graphics-drivers/ppa
</code></pre><p>安装或更新到最新的 Nvidia 显卡驱动：</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get install nvidia-355
</code></pre><p>记住：如果PPA把你的系统弄崩了，你可得自己去想办法，我们提醒过了哦。（译者注：切记！）</p><p>如果想要撤销对PPA的改变，使用 <code>ppa-purge</code> 命令。</p><p>有什么意见，想法，或者指正，就在下面的评论栏里写下来吧。（我没有 NVIDIA 的硬件来为我自己验证上面的这些东西，如果你可以验证的话，那就太感谢了。）</p><hr>`,21)),p("p",null,[t[4]||(t[4]=r("via: ",-1)),e(n,{href:"http://www.omgubuntu.co.uk/2015/08/ubuntu-nvidia-graphics-drivers-ppa-is-ready-for-action"},{default:o(()=>[...t[3]||(t[3]=[r("http://www.omgubuntu.co.uk/2015/08/ubuntu-nvidia-graphics-drivers-ppa-is-ready-for-action",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=r("作者：",-1)),e(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:o(()=>[...t[5]||(t[5]=[r("Joey-Elijah Sneddon",-1)])]),_:1}),t[9]||(t[9]=r(" 译者：",-1)),e(n,{href:"https://github.com/DongShuaike"},{default:o(()=>[...t[6]||(t[6]=[r("DongShuaike",-1)])]),_:1}),t[10]||(t[10]=r(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[7]||(t[7]=[r("wxy",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=r("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[r("LCTT",-1)])]),_:1}),t[14]||(t[14]=r(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[r("Linux中国",-1)])]),_:1}),t[15]||(t[15]=r(" 荣誉推出",-1))])])}const N=i(l,[["render",P]]);export{v as __pageData,N as default};
